{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four datasets, couple a lower Adam learning rate with mild weight decay to moderate updates and regularize parameters. Retain history length 64, hidden size 64, six causal convolution blocks, dropout 0.15 and batch size 128. Architecture, features, loss, predictor compatibility and training caps remain unchanged.",
      "edits": [
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"8e-4\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"6e-4\"))"
        },
        {
          "find": "WEIGHT_DECAY  = float(os.environ.get(\"NEXTITNET_WD\", \"0.0\"))",
          "replace": "WEIGHT_DECAY  = float(os.environ.get(\"NEXTITNET_WD\", \"1e-5\"))"
        }
      ]
    }
  ],
  "change_summary": "Set shared Adam defaults to learning rate 6e-4 and weight decay 1e-5 for the four independent category models. No predictor changes are needed."
}
